using System;
using System.IO;
using System.Text;
using Newtonsoft.Json.Linq;
using XanaduYonder.Core;
using XanaduYonder.Core.Sokoban;
using XanaduYonder.Runtime.Sokoban;
internal static class Program
{
    static int passed;
    static SokobanCatalog catalog;
    static void Main()
    {
        catalog=SokobanCatalog.Parse(CatalogJson());
        Check("catalog schema, duplicate identity and map validation",()=>{
            Equal(catalog.Count,2);Equal(catalog.Get("test-a").Width,6);Assert(catalog.At(0).Solution=="RR");
            Reject(()=>SokobanCatalog.Parse(CatalogJson().Replace("\"schemaVersion\":1","\"schemaVersion\":2")));
            var root=JObject.Parse(CatalogJson());root["levels"][1]["levelId"]="test-a";Reject(()=>SokobanCatalog.Parse(root.ToString()));
        });
        Check("session gates stale actions and lifecycle",()=>{var s=Session();Assert(!s.Execute("stale",Direction.Right).Changed);s.SetBlocked(true);Assert(!s.Move(Direction.Right).Changed);s.SetBlocked(false);s.SetForeground(false);Assert(!s.Move(Direction.Right).Changed);s.SetForeground(true);s.Leave();Assert(!s.Move(Direction.Right).Changed);s.Enter();Assert(s.Move(Direction.Right).Changed);});
        Check("completed levels deduplicate and restarting changes attempt",()=>{var p=new SokobanProfile(catalog);var s=Session();s.Move(Direction.Right);s.Move(Direction.Right);var data=p.Capture(s);Assert(s.ResultRecorded);Equal(p.CompletedCount,1);p.Capture(s);Equal(p.CompletedCount,1);var restored=new SokobanSession(data.ActiveAttempt,catalog);p.Capture(restored);Equal(p.CompletedCount,1);string id=s.AttemptId;s.Restart();Assert(id!=s.AttemptId);Equal(s.Game.Moves,0);Equal(p.CompletedCount,1);});
        Check("best tuples are real performances, not component minima",()=>{var r=new SokobanRecord();r.Consider(20,10);r.Consider(30,5);Equal(r.BestMoves.Moves,20);Equal(r.BestMoves.Pushes,10);Equal(r.BestPushes.Moves,30);Equal(r.BestPushes.Pushes,5);r.Consider(20,8);Equal(r.BestMoves.Pushes,8);r.Consider(25,5);Equal(r.BestPushes.Moves,25);});
        Check("one active attempt and defensive copies",()=>{var p=new SokobanProfile(catalog);var s=p.StartLevel("test-a");s.Move(Direction.Right);p.Capture(s);var a=p.GetActive();a.Boxes[0]=0;Assert(p.GetActive().Boxes[0]!=0);p.StartLevel("test-b");Assert(p.GetActive().LevelId=="test-b");Equal(p.GetActive().Moves,0);});
        Check("roundtrip replays all moves and preserves undo",()=>{var s=Session();s.Move(Direction.Right);s.SetView(1.5,.7,.3);var p=new SokobanProfile(catalog);string json=SokobanSaveCodec.Encode(p.Capture(s),catalog);Assert(SokobanSaveCodec.TryDecode(json,catalog,out var data,out var why),why);var restored=new SokobanSession(data.ActiveAttempt,catalog);Equal(restored.Game.Moves,1);Assert(restored.Undo());Equal(restored.Game.Player,catalog.At(0).InitialPlayer);Assert(restored.Zoom==1.5);});
        Check("replay rejects altered current state, counts and blocked history",()=>{Mutate(r=>r["activeAttempt"]["player"]=8);Mutate(r=>r["activeAttempt"]["moves"]=2);Mutate(r=>r["activeAttempt"]["pushes"]=1);Mutate(r=>r["activeAttempt"]["actions"]="U");Mutate(r=>r["activeAttempt"]["boxes"][0]=0);Mutate(r=>r["activeAttempt"]["won"]=true);});
        Check("every mandatory root and nested field rejects missing null and wrong type",()=>{var root=JObject.Parse(Valid());foreach(var path in new[]{"", "activeAttempt", "activeAttempt.viewport"}){var obj=path.Length==0?root:(JObject)root.SelectToken(path);foreach(var property in obj.Properties()){var field=property.Name;foreach(int mode in new[]{0,1,2}){if(path.Length==0&&field=="activeAttempt"&&mode==1)continue;var clone=JObject.Parse(Valid());var target=path.Length==0?clone:(JObject)clone.SelectToken(path);if(mode==0)target.Remove(field);else target[field]=mode==1?JValue.CreateNull():(property.Value.Type==JTokenType.Array?(JToken)new JValue("wrong-type"):new JArray());Bad(clone.ToString());}}}});
        Check("duplicate keys standard JSON depth and UTF8 byte cap",()=>{Bad(Valid().Replace("\"schemaVersion\":1","\"schemaVersion\":1,\"schemaVersion\":1"));Bad("/*comment*/"+Valid());Bad(Valid().Replace("\"gameId\"","gameId"));Bad(Valid().Replace("\"gameId\"","'gameId'"));Bad(Valid().TrimEnd('}')+",}");Bad(Valid()+" true");Bad(new string('[',13)+new string(']',13));Bad(new string(' ',SokobanSaveCodec.MaximumLength+1));Bad(Valid().Replace("\"sokoban\"","\""+new string('中',750000)+"\""));});
        Check("viewport numeric finite and clamp normalization",()=>{foreach(string v in new[]{"null","\"1.5\"","true","NaN","1e999"})Bad(Valid().Replace("\"zoom\":1.0","\"zoom\":"+v));var root=JObject.Parse(Valid());root["activeAttempt"]["viewport"]["zoom"]=3;root["activeAttempt"]["viewport"]["centerX"]=-2;root["activeAttempt"]["viewport"]["centerY"]=7;Assert(SokobanSaveCodec.TryDecode(root.ToString(),catalog,out var d,out var reason),reason);Assert(d.ActiveAttempt.Zoom==2&&d.ActiveAttempt.CenterX==0&&d.ActiveAttempt.CenterY==1);root["activeAttempt"]["viewport"]["zoom"]=.3;Assert(SokobanSaveCodec.TryDecode(root.ToString(),catalog,out d,out reason),reason);Assert(d.ActiveAttempt.Zoom==1&&d.ActiveAttempt.CenterX==.5&&d.ActiveAttempt.CenterY==.5);});
        Check("content migration keeps known records and discards coordinates",()=>{var p=new SokobanProfile(catalog);var s=Session();s.Move(Direction.Right);s.Move(Direction.Right);var root=JObject.Parse(SokobanSaveCodec.Encode(p.Capture(s),catalog));root["contentVersion"]="old-version";Assert(SokobanSaveCodec.TryDecode(root.ToString(),catalog,out var d,out var why),why);Assert(d.ActiveAttempt==null&&d.RestoreWarning!=null);Equal(d.CompletedLevelIds.Length,1);Assert(new SokobanProfile(catalog,d).IsCompleted("test-a"));});
        Check("encode rejects impossible current occupancy before any file write",()=>{var d=Data();d.ActiveAttempt.Player=0;Reject(()=>SokobanSaveCodec.Encode(d,catalog));d=Data();d.ActiveAttempt.Boxes[0]=0;Reject(()=>SokobanSaveCodec.Encode(d,catalog));});
        Check("restore accepts 50000 complete actions and rejects over-limit or post-win history",()=>{var root=JObject.Parse(Valid());string actions=new string('R',0);var builder=new StringBuilder();for(int i=0;i<25000;i++)builder.Append("RL");actions=builder.ToString();root["activeAttempt"]["actions"]=actions;root["activeAttempt"]["moves"]=50000;Assert(SokobanSaveCodec.TryDecode(root.ToString(),catalog,out var d,out var why),why);var restored=new SokobanSession(d.ActiveAttempt,catalog);Assert(restored.Game.AtMoveLimit);Assert(restored.Undo());Equal(restored.Game.Moves,49999);root["activeAttempt"]["actions"]=actions+"R";root["activeAttempt"]["moves"]=50001;Bad(root.ToString());var p=new SokobanProfile(catalog);var s=Session();s.Move(Direction.Right);s.Move(Direction.Right);root=JObject.Parse(SokobanSaveCodec.Encode(p.Capture(s),catalog));root["activeAttempt"]["actions"]="RRL";root["activeAttempt"]["moves"]=3;root["activeAttempt"]["player"]=8;Bad(root.ToString());});
        Check("result record and terminal consistency reject forged accounting",()=>{Mutate(r=>r["activeAttempt"]["resultRecorded"]=true);var p=new SokobanProfile(catalog);var s=Session();s.Move(Direction.Right);s.Move(Direction.Right);var root=JObject.Parse(SokobanSaveCodec.Encode(p.Capture(s),catalog));root["completedLevelIds"]=new JArray();Bad(root.ToString());root=JObject.Parse(SokobanSaveCodec.Encode(p.Capture(s),catalog));root["activeAttempt"]["resultRecorded"]=false;Bad(root.ToString());});
        Check("atomic main and valid backup restore and corrupt archives",()=>WithDirectory(dir=>{var store=new SokobanSaveStore(dir,catalog);Assert(store.Load(out var warning)==null&&warning==null);var data=Data();Assert(store.TrySave(data,out var error),error);var s=Session();s.Move(Direction.Right);var p=new SokobanProfile(catalog);Assert(store.TrySave(p.Capture(s),out error),error);Assert(File.Exists(store.SavePath+".bak"));File.WriteAllText(store.SavePath,"broken");var recovery=new SokobanSaveStore(dir,catalog);var recovered=recovery.Load(out warning);Assert(recovered!=null&&warning!=null);Equal(recovered.ActiveAttempt.Moves,0);Assert(recovery.TrySave(recovered,out error),error);Assert(new SokobanSaveStore(dir,catalog).Load(out warning)!=null);File.WriteAllText(store.SavePath,"broken main");File.WriteAllText(store.SavePath+".bak","broken backup");Assert(new SokobanSaveStore(dir,catalog).Load(out warning)==null&&warning!=null);Assert(Directory.GetFiles(dir,"*.corrupt-*").Length>=2);}));
        Check("failed write preserves valid committed data and allows retry",()=>WithDirectory(dir=>{var store=new SokobanSaveStore(dir,catalog);Assert(store.TrySave(Data(),out var error),error);string before=File.ReadAllText(store.SavePath);Directory.CreateDirectory(store.SavePath+".tmp");Assert(!store.TrySave(Data(),out error)&&error!=null);Assert(File.ReadAllText(store.SavePath)==before);Directory.Delete(store.SavePath+".tmp");Assert(store.TrySave(Data(),out error),error);Assert(error==null);}));
        Check("externally corrupted main never displaces a valid backup",()=>WithDirectory(dir=>{var store=new SokobanSaveStore(dir,catalog);Assert(store.TrySave(Data(),out var error),error);Assert(store.TrySave(Data(),out error),error);string goodBackup=File.ReadAllText(store.SavePath+".bak");File.WriteAllText(store.SavePath,"externally corrupted");Assert(store.TrySave(Data(),out error),error);Assert(File.ReadAllText(store.SavePath+".bak")==goodBackup);Assert(Directory.GetFiles(dir,"*.corrupt-*").Length==1);}));
        Check("invalid UTF8 and inaccessible path report error",()=>WithDirectory(dir=>{var store=new SokobanSaveStore(dir,catalog);File.WriteAllBytes(store.SavePath,new byte[]{0xff,0xfe});Assert(store.Load(out var warning)==null&&warning!=null);var invalid=new SokobanSaveStore(store.SavePath,catalog);Assert(!invalid.TrySave(Data(),out var error)&&error!=null);}));
        Console.WriteLine("Sokoban persistence/session: "+passed+" passed");
    }
    static string CatalogJson(){return "{\"schemaVersion\":1,\"contentVersion\":\"v1\",\"levels\":["+LevelJson("test-a",1,"#@ $.#","RR")+","+LevelJson("test-b",2,"# @$.#","R")+"]}";}
    static string LevelJson(string id,int order,string row,string solution){return "{\"schemaVersion\":1,\"levelId\":\""+id+"\",\"contentVersion\":\"v1\",\"chapter\":\"tutorial\",\"order\":"+order+",\"title\":\"Test\",\"source\":{\"collection\":\"xanadu-original\",\"sourceId\":\""+id+"\"},\"rows\":[\"######\",\""+row+"\",\"######\"],\"solution\":\""+solution+"\"}";}
    static SokobanSession Session(){return new SokobanSession(catalog.At(0));}
    static SokobanSaveData Data(){var p=new SokobanProfile(catalog);return p.Capture(Session());}
    static string Valid(){return SokobanSaveCodec.Encode(Data(),catalog);}
    static void Mutate(Action<JObject> mutate){var root=JObject.Parse(Valid());mutate(root);Bad(root.ToString());}
    static void Bad(string json){Assert(!SokobanSaveCodec.TryDecode(json,catalog,out var d,out var why),"Accepted invalid: "+json.Substring(0,Math.Min(json.Length,180)));Assert(d==null&&why!=null);}
    static void WithDirectory(Action<string> action){var dir=Path.Combine(Path.GetTempPath(),"sokoban-check-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{action(dir);}finally{Directory.Delete(dir,true);}}
    static void Check(string name,Action run){run();passed++;Console.WriteLine("PASS "+name);}
    static void Equal(int a,int b){Assert(a==b,a+" != "+b);}
    static void Assert(bool value,string message="Assertion failed"){if(!value)throw new Exception(message);}
    static void Reject(Action a){try{a();}catch(ArgumentException){return;}catch(FormatException){return;}throw new Exception("Expected rejection");}
}
